<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_role('student');$page_title='Моя статистика';
$q=$pdo->prepare('SELECT id FROM students WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$sid=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT s.id,s.name subject_name,COUNT(a.id) total,SUM(a.status='PRESENT') present,SUM(a.status='ABSENT') absent,SUM(a.status='LATE') late,SUM(a.status='EXCUSED') excused FROM subjects s LEFT JOIN lessons l ON l.subject_id=s.id LEFT JOIN attendance a ON a.lesson_id=l.id AND a.student_id=? GROUP BY s.id HAVING total>0 ORDER BY s.name");$q->execute([$sid]);$att=$q->fetchAll();
$q=$pdo->prepare('SELECT s.name subject_name,ROUND(AVG(g.grade),2) avg_grade,COUNT(g.id) cnt FROM grades g JOIN subjects s ON s.id=g.subject_id WHERE g.student_id=? GROUP BY s.id ORDER BY s.name');$q->execute([$sid]);$grades=$q->fetchAll();include '../includes/header.php';?>
<div class="statistics-grid"><div class="panel statistics-panel"><h2>Посещаемость по предметам</h2><div class="table-wrap"><table><tr><th>Предмет</th><th>Всего</th><th>Был</th><th>Пропуск</th><th>Опоздания</th><th>%</th></tr><?php foreach($att as $r):$pct=$r['total']?round(($r['present']+$r['late'])/$r['total']*100):0;?><tr><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=$r['total']?></td><td><?=$r['present']?></td><td><?=$r['absent']?></td><td><?=$r['late']?></td><td><b><?=$pct?>%</b><div class="progress"><i style="width:<?=$pct?>%"></i></div></td></tr><?php endforeach;?></table></div></div><div class="panel statistics-panel"><h2>Успеваемость</h2><?php if($grades):?><div class="table-wrap"><table><tr><th>Предмет</th><th>Оценок</th><th>Средний</th></tr><?php foreach($grades as $r):?><tr><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=$r['cnt']?></td><td><b><?=$r['avg_grade']?></b></td></tr><?php endforeach;?></table></div><?php else:?><div class="empty-state">Оценок пока нет.</div><?php endif;?></div></div>
<?php include '../includes/footer.php';?>
